    /**
     * 解析URL参数的方法
     * @param url
     * @returns
     */
    private static getURLParameters(url: string): any {
        const params: any = {};
        url.replace(/[?&]+([^=&]+)=([^&]*)/gi, (_match: string, key: any, value: any): string => (params[key] = decodeURIComponent(value)));
        return params;
    }

    /**
     * 检查字符串是否只包含英文字母、数字、下划线、连字符和空格
     * @param nameStr 需要检查的字符串
     * @returns 如果字符串只包含允许的字符返回true，否则返回false
     */
    public static cheakStr(nameStr: string): boolean {
        let checkStr: RegExp = new RegExp("[A-Za-z0-9_-\\s]", "g");
        let ary: any[] = nameStr.match(checkStr);
        if (ary && ary.length == nameStr.length) {
            return true;
        }
        return false;
    }

    /**
     * 验证字符串是否为有效的数字格式
     * @param nameStr 需要验证的字符串
     * @returns 如果是有效的数字格式返回true，否则返回false
     * @description 正则表达式说明：
     * ^(?!0\d) - 不允许以0开头的多位数字（但允许单个0）
     * \d*\.?\d*$ - 允许整数或小数，小数点前后的数字位数不限
     */
    public static isNumber(nameStr: string): boolean {
        const numberPattern = /^(?!0\d)\d*\.?\d*$/;
        const isnumber = numberPattern.test(nameStr);
        return isnumber;
    }

    /**
     * 将数字转换为字符串，整数保持原样，小数保留两位且去除末尾多余的0
     * @param num 需要处理的数字
     * @returns 处理后的字符串
     * @example
     * roundToTwoDecimals(5) => "5"
     * roundToTwoDecimals(5.00) => "5"
     * roundToTwoDecimals(5.20) => "5.2"
     * roundToTwoDecimals(5.206) => "5.21"
     */
    public static roundToTwoDecimals(num: number): string {
        // 如果数字本身是整数，直接返回整数部分
        if (num % 1 === 0) {
            // 如果是整数，直接返回整数部分
            return num.toString();
        } else {
            // 将数字保留两位小数，同时不显示多余的零
            return Number(num.toFixed(2)).toString();
        }
    }

