    /**
     * 格式化数字，限制小数位数
     * @param num 需要格式化的数字
     * @param dec 保留的小数位数，默认为7位
     * @returns 格式化后的数字
     * @example
     * formatNumber(123.4567891) => 123.4567891
     * formatNumber(123.4567891, 4) => 123.4567
     */
    public static formatNumber(num: number, dec: number = 7): number {
        // 判断小数点后是否大于6位
        let numString: string = num.toString();
        let decimalIndex: number = numString.indexOf(".");
        if (decimalIndex !== -1 && numString.length - decimalIndex > dec) {
            // 截取小数点后6位
            numString = numString.slice(0, decimalIndex + dec);
            return parseFloat(numString);
        }
        return num;
    }

    /**
     * 将数字截断到指定小数位数（固定为4位）
     * @param number 需要截断的数字
     * @returns 截断后的数字
     * @example
     * truncateToTwoDecimalPlaces(123.456789) => 123.4567
     * truncateToTwoDecimalPlaces(123) => 123
     */
    public static truncateToTwoDecimalPlaces(number: number): number {
        // 使用字符串方法来截取小数点后两位
        const numberString = number.toString();
        const decimalPointIndex = numberString.indexOf(".");

        // 如果没有小数点，直接返回原数
        if (decimalPointIndex === -1) {
            return number;
        }

        // 截取到小数点后两位
        const truncatedNumberString = numberString.substring(0, decimalPointIndex + 5);
        return parseFloat(truncatedNumberString);
    }

    /**
     * 根据枚举值获取对应的枚举键名
     * @param enumObj 枚举对象
     * @param value 枚举值
     * @returns 对应的枚举键名，如果未找到则返回undefined
     * @example
     * enum Color { Red = 1, Blue = 2 }
     * getKeyByValue(Color, 1) => "Red"
     */
    public static getKeyByValue(enumObj: any, value: number): string | undefined {
        return Object.keys(enumObj).find((key) => enumObj[key] === value);
    }

    /**
     * 计算一个数字的10的n次方
     * @param num 基数
     * @param decimals 指数
     * @returns 计算结果 (num * 10^decimals)
     * @example
     * powerOf10(2, 3) => 2000 // 2 * 10^3
     * powerOf10(5, 2) => 500 // 5 * 10^2
     */
    public static powerOf10(num: number, decimals: number): number {
        return num * Math.pow(10, decimals);
    }

    /**
     * 判断是否为闰年的函数
     * @param year
     * @returns
     */
    public static isLeapYear(year: number): boolean {
        return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
    }

    /**
     * 根据年份和月份获取该月的天数
     * @param year
     * @param month
     * @returns
     */
    public static getDaysInMonth(year: number, month: number): number {
        if (month === 2) {
            return this.isLeapYear(year) ? 29 : 28; // 闰年2月份有29天，否则有28天
        } else if ([4, 6, 9, 11].includes(month)) {
            return 30; // 4、6、9、11月份有30天
        } else {
            return 31; // 其他月份都有31天
        }
    }

    /**
     * 将长钱包地址转为短钱包地址
     * @param str
     * @param prefixLength
     * @param suffixLength
     * @returns
     */
    public static shortenString(str: string, prefixLength: number, suffixLength: number): string {
        if (str.length <= prefixLength + suffixLength) {
            return str; // 如果字符串长度不足前8位加后6位，则直接返回原字符串
        } else {
            return str.substr(0, prefixLength) + "..." + str.substr(-suffixLength);
        }
    }

    /**
     * 执行大数相乘操作，通过高精度因子来避免JavaScript浮点数计算的精度损失
     * @param num1 第一个乘数，可以是数字或字符串类型
     * @param num2 第二个乘数，可以是数字或字符串类型
     * @returns 返回两个数相乘的结果，精度由precision控制
     */
    public static multiplyBigDecimals(num1: number | string, num2: number | string): number {
        const precision = 10000; // 设定精度
        const factor = Math.pow(10, precision);

        const result = parseFloat(String(num1)) * parseFloat(String(num2));
        return Math.round(result * factor) / factor;
    }

    /**
     * 判断数组是否相等
     * @param arr1
     * @param arr2
     * @returns
     */
    public static arraysEqual(arr1: any[], arr2: any[]): boolean {
        return arr1.length === arr2.length && arr1.every((value, index) => value === arr2[index]);
    }

    /**
     * 合并同类数组
     * @param a
     * @param b
     * @returns
     */
    public static categorizeArrays(a: any[], b: any) {
        const result = [];
        for (const itemB of b) {
            const keyB = itemB[0];
            const valueB = itemB[1];

            // 在 b 中查找是否有相同的第一个元素
            const found = a.find((itemA: any[]) => itemA[0] === keyB);
            const valueA = found ? found[1] : 0; // 如果找到，获取第二个值，否则为 0

            result.push([keyB, valueA, valueB]);
        }

        return result;
    }

