const { regClass } = Laya;
import { BtnColorFilter } from "../../common/filters/BtnColorFilter";

import { ItemItem } from "../../data/sheetItem/item/ItemItem";
import { GameEvent } from "../../global/event/GameEvent";
import Signal from "../../global/event/Signal";
import { MatchSkillListItemBase } from "./MatchSkillListItem.generated";

@regClass('x6t+z1VuR52yXWju0qxGBg==')
export class MatchSkillListItem extends MatchSkillListItemBase {
    public skillItem: any;
    public itemItem: ItemItem;
    private isAddEvent: boolean = false;
    private isCanClick = true;
    public keyNum: number;
    public equipPos: number;
    public count: number;

    public constructor() {
        super();
    }

    onEnable(): void {
        this.addEvent();
    }

    private addEvent() {
        if (!this.isAddEvent) {
            Signal.on(GameEvent.EVENT_CLICK_NUM, this, this.onNumberClick);
            Signal.on(GameEvent.EVENT_UPDATE_ITEM_SKILL_COOL, this, this.updateItemRemainCooldown);
            // Signal.on(GameEvent.EVENT_UPDATE_GLOBAL_COOL, this, this.updateGlobalCooldown);
            Signal.on(GameEvent.EVENT_UPDATE_REDECE_COOL, this, this.updateReduceCooldown);
            // this.on(Laya.Event.CLICK, this, this.onSkillButtonClick);
            this.isAddEvent = true;

            this.on(Laya.Event.CLICK, this, this.onSkillButtonClick);
            this.on(Laya.Event.MOUSE_UP, this, this.onSkillButtonUp);
        }
    }

    onNumberClick(num: number) {
        if (num == this.keyNum) {
            // if(!this.isBig)
            this.onSkillButtonClick(null);
        }
    }

    public set dataSource(value: any) {
        if(!value) return;
        super.dataSource = value;
        this.skillItem = value[0];
        this.itemItem = value[1] as ItemItem;
        this.equipPos = value[2];
        this.count = value[3];
        if (!this.skillItem) {
            return;
        }
        this.addEvent();
        this.setCurrentOutPut();
    }

    async setCurrentOutPut() {
        if (!this.skillItem) return;

        this.skillIconItem.dataSource = this.skillItem;

        // this.skillIconItem.txt_num.text = '' + this.skillItem.name;//TODO TEST
        // this.skillIconItem.txt_num.visible = true;//TODO TEST

        if (this.itemItem) {
            this.txt_num.visible = true;
            this.updateCount();
            this.skillCooldown = this.itemItem.cd * 1000; // 技能冷却时间（毫秒）
        } else {
            this.txt_num.visible = false;
            this.skillCooldown = this.skillItem.cd; // 技能冷却时间（毫秒）
        }
    }

    private skillCooldown: number = 5000; // 技能冷却时间（毫秒）

    // 技能按钮点击事件
    private onSkillButtonUp(e: Laya.Event): void {
        if (e) {
            e.stopPropagation();
        }
        BtnColorFilter.clearClickFilter(this);
    }

    // 技能按钮点击事件
    private onSkillButtonClick(e: Laya.Event): void {
        if (e) {
            e.stopPropagation();
        }
        return;
    }

    /**
     * 更新道具冷却
     * @param _skillId
     */
    public updateItemRemainCooldown(updateData: any[]) {
        var _skillId: number = updateData[0];

        console.log("updateItemRemainCooldown _skillId: " + _skillId);
        if (this.itemItem && _skillId == this.skillItem.id) {
            this.count = updateData[1];
            this.updateCount();
        }
    }

    updateCount() {
        this.txt_num.text = this.count + "";
        this.disabled = !this.count;
    }
    /**
     * 更新道具冷却
     * @param _skillId
     */
    public updateReduceCooldown(skillType: number, reduceRate: number) {
        console.log("updateReduceCooldown skillType: " + skillType);
        // if (this.skillItem && skillType == this.skillItem.type) {
        //     this.reduceCooldown = this.skillCooldown * reduceRate;
        // }
    }

    onDisable(): void {
        Signal.off(GameEvent.EVENT_UPDATE_ITEM_SKILL_COOL, this, this.updateItemRemainCooldown);
        // Signal.off(GameEvent.EVENT_UPDATE_GLOBAL_COOL, this, this.updateGlobalCooldown);
        Signal.off(GameEvent.EVENT_UPDATE_REDECE_COOL, this, this.updateReduceCooldown);
        Signal.offAllCaller(this);
        Laya.timer.clearAll(this);
    }
}
