    /**
     * 接收列表数据回调
     */
    private onlist_dataReceived(msgBase: com.snake.socket.CMsgBase): void {
        // 隐藏加载中效果
        // this.showLoading(false);
        var raceId = EnterRoomManager.raceId;

        // 解析数据
        const rankListData: com.snake.socket.SC_RACE_LIST = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_RACE_LIST);
        console.log(rankListData);
        var rankData = [];
        if (rankListData && rankListData.info) {
            var now = new Date().getTime();
            for (var i = 0; i < rankListData.info.length; i++) {
                var infoStr = rankListData.info[i]; //创建信息json|参数人数|是否已报名
                var infos = infoStr.split("|");
                var raceDto: com.snake.socket.CS_CREATE_RACE = JSON.parse(infos[0]);
                console.log("raceDto: ", raceDto);
                var raceVo = new RaceVo();
                raceVo.raceDto = raceDto;
                raceVo.playerNum = parseInt(infos[1]);
                raceVo.isSign = infos[2] == "true";
                if (raceDto.endTime < now) {
                    //比赛已结束
                    if (this.currentTabIndex == 1) {
                        rankData.push(raceVo);
                    }
                } else {
                    if (this.currentTabIndex == 0) {
                        rankData.push(raceVo);
                    }
                }
                if(raceId && raceId==raceDto.id){
                    Signal.event(GameEvent.MATCH_TOURNAMENT_RACE_DATA_UPDATE, raceVo);

                }
            }
        }

        if (rankData.length === 0) {
            this.list_data.visible = false;
            this.noDataBox.visible = true;
        } else {
            this.list_data.visible = true;
            this.noDataBox.visible = false;
            this.list_data.array = rankData;
            if (this.lastTabIndex != this.currentTabIndex) {
                // 滚动到列表的第一行
                this.list_data.scrollTo(0);
            }
            this.lastTabIndex = this.currentTabIndex;
        }
    }

    /**
     * 接收排行榜数据回调
     */
    private onRaceSignBack(raceId: number): void {
        if (raceId) {
            console.log("接收排行榜数据回调");
            this.requestRankData(0);
        }
    }

    onDisable(): void {
        this.removeEvent();
        Laya.timer.clearAll(this);
    }
