const { regClass } = Laya;
import { ShopItem } from "../../data/sheetItem/shop/ShopItem";
import { ShopListItemBase } from "./ShopListItem.generated";
import { ModuleManager } from "../../common/ModuleManager";
import { ModuleName } from "../../global/ModuleName";
import { ItemItem } from "../../data/sheetItem/item/ItemItem";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import GameResourceManager from "../../common/GameResourceManager";
import SheetDataManager from "../../global/SheetDataManager";

@regClass('awS07ko0RBaxCnxXWqiR4g==')
export class ShopListItem extends ShopListItemBase {
    public shopItem: ShopItem;

    public constructor() {
        super();
    }

    onEnable(): void {
        this.on(Laya.Event.CLICK, this, this.toShowBuyDialog);
    }

    public set dataSource(value: ShopItem) {
        super.dataSource = value;
        this.shopItem = value as ShopItem;
        if (!this.shopItem) {
            return;
        }
        this.tf_const.text = `${this.shopItem.cost} USDT`;
        const itemItem: ItemItem = SheetDataManager.m_dicItems.get(this.shopItem.itemId);
        if (!itemItem) {
            return;
        }
        this.tf_name.text = GameLanguageMgr.getLanguage(itemItem.name);
        // 检测文本是否换行，根据换行情况调整y轴坐标
        const textHeight = this.tf_name.height;
        const lineHeight = this.tf_name.fontSize;
        // this.tf_name.y = textHeight > lineHeight ? 226 : 244;
        this.img_icon.skin = GameResourceManager.getItemIcon(itemItem);
    }

    private toShowBuyDialog() {
        ModuleManager.intance.openModule(ModuleName.BuyPropDialog, this.shopItem);
    }
}
