/**
 * 方块单元格类
 * 用于存储单个方块的数据，替代原来的数字存储方式
 */
export class Cell {
    public color: number = 0;        // 颜色值 (0表示空)
    public isfixed: boolean = false;  // 是否已固定 (非当前下落方块)
    public isfalling: boolean = false; // 是否正在下落
    public isContinueDrop: boolean = false; // 是否为连续下落筛选标记

    constructor() {
        this.color = 0;
        this.isfixed = false;
        this.isfalling = false;
        this.isContinueDrop = false;
    }

    /**
     * 设置为空单元格
     */
    public setEmpty(): void {
        this.color = 0;
        this.isfixed = false;
        this.isfalling = false;
        this.isContinueDrop = false;
    }

    /**
     * 检查是否为空单元格
     */
    public isEmpty(): boolean {
        return this.color === 0;
    }

    /**
     * 设置单元格数据
     */
    public setCell(color: number, isfixed: boolean = false, isfalling: boolean = false, isContinueDrop: boolean = false): void {
        this.color = color;
        this.isfixed = isfixed;
        this.isfalling = isfalling;
        this.isContinueDrop = isContinueDrop;
    }

    /**
     * 复制另一个单元格的数据
     */
    public copyFrom(other: Cell): void {
        this.color = other.color;
        this.isfixed = other.isfixed;
        this.isfalling = other.isfalling;
        this.isContinueDrop = other.isContinueDrop;
    }

    /**
     * 克隆当前单元格
     */
    public clone(): Cell {
        const newCell = new Cell();
        newCell.copyFrom(this);
        return newCell;
    }

    /**
     * 复制当前单元格（与clone方法相同）
     */
    public copy(): Cell {
        return this.clone();
    }

    /**
     * 设置颜色
     */
    public setColor(color: number): void {
        this.color = color;
    }

    /**
     * 获取颜色
     */
    public getColor(): number {
        return this.color;
    }

    /**
     * 设置固定状态
     */
    public setFixed(fixed: boolean): void {
        this.isfixed = fixed;
    }

    /**
     * 检查是否已固定
     */
    public isFixed(): boolean {
        return this.isfixed;
    }

    /**
     * 设置下落状态
     */
    public setFalling(falling: boolean): void {
        this.isfalling = falling;
    }

    /**
     * 检查是否正在下落
     */
    public isFalling(): boolean {
        return this.isfalling;
    }

    public setContinueDrop(val: boolean): void {
        this.isContinueDrop = val;
    }
    public getContinueDrop(): boolean {
        return this.isContinueDrop;
    }
}