import { TetrisType } from "./GameManager";

/**
 * 形状识别结果接口
 */
export interface ShapeIdentification {
    type: TetrisType;
    rotation: number;
    isValid: boolean;
    shapeName: string;
    additionalOffsetX: number;
    additionalOffsetY: number;
    width: number; // 形状在当前旋转状态下的宽度（列数）
}

/**
 * 俄罗斯方块形状管理器
 * 负责形状的识别、判断和管理
 */
export class ShapeManager {
    
    /**
     * 根据传入的形状矩阵识别形状类型和旋转状态
     * @param shape 形状矩阵
     * @returns 形状识别结果
     */
    public static identifyShape(shape: number[][]): ShapeIdentification {
        if (!shape || shape.length === 0) {
            return {
                type: TetrisType.I,
                rotation: 0,
                isValid: false,
                shapeName: "Invalid",
                additionalOffsetX: 0,
                additionalOffsetY: 0,
                width: 0
            };
        }

        // 将形状矩阵转换为字符串用于比较
        const shapeString = this.shapeToString(shape);
        
        // 使用switch语句判断形状（去除重复判断）
        switch (shapeString) {
            // I形方块 - 2种独特形状
            case "0000,1111,0000,0000": // I形 0°/180°
            case "0000,0000,1111,0000": // I形 0°/180°
            case "1111,0000,0000,0000": // I形 0°/180°
            case "0000,0000,0000,1111": // I形 0°/180°
                return { type: TetrisType.I, rotation: 0, isValid: true, shapeName: "I-Horizontal", additionalOffsetX: 46.3, additionalOffsetY: 0, width: 4 };
            case "1000,1000,1000,1000": // I形 90°/270° (4x4矩阵中间列)
            case "0100,0100,0100,0100": // I形 90°/270°
            case "0010,0010,0010,0010": // I形 90°/270° (4x4矩阵中间列)
            case "0001,0001,0001,0001": // I形 90°/270° (4x4矩阵中间列)
                return { type: TetrisType.I, rotation: 90, isValid: true, shapeName: "I-Vertical", additionalOffsetX: 63, additionalOffsetY: 71, width: 1 };
            case "0,1,1,0": // I形 90°/270° (紧凑格式)
                return { type: TetrisType.I, rotation: 90, isValid: true, shapeName: "I-Vertical", additionalOffsetX: 63, additionalOffsetY: 71, width: 1 };
            case "1,1,1,1": // I形 90°/270° (4个连续的1)
                return { type: TetrisType.I, rotation: 90, isValid: true, shapeName: "I-Vertical", additionalOffsetX: 63, additionalOffsetY: 71, width: 1 };
           

            // J形方块 - 4种独特形状
            case "100,111,000": // J形 0°
                return { type: TetrisType.J, rotation: 0, isValid: true, shapeName: "J-Standard", additionalOffsetX: 40, additionalOffsetY: 0, width: 3 };
            case "011,010,010": // J形 90°
                return { type: TetrisType.J, rotation: 90, isValid: true, shapeName: "J-Right", additionalOffsetX: 52.5, additionalOffsetY: 37.5, width: 2 };
            case "000,111,001": // J形 180°
                return { type: TetrisType.J, rotation: 180, isValid: true, shapeName: "J-Inverted", additionalOffsetX: 0, additionalOffsetY: 0, width: 3 };
            case "010,010,110": // J形 270°
                return { type: TetrisType.J, rotation: 270, isValid: true, shapeName: "J-Left", additionalOffsetX: 0, additionalOffsetY: 37.5, width: 2 };

            // L形方块 - 4种独特形状
            case "001,111,000": // L形 0°
                return { type: TetrisType.L, rotation: 0, isValid: true, shapeName: "L-Standard", additionalOffsetX: 32.5, additionalOffsetY: 0, width: 3 };
            case "010,010,011": // L形 90°
                return { type: TetrisType.L, rotation: 90, isValid: true, shapeName: "L-Right", additionalOffsetX: 60, additionalOffsetY: 37.5, width: 2 };
            case "000,111,100": // L形 180°
                return { type: TetrisType.L, rotation: 180, isValid: true, shapeName: "L-Inverted", additionalOffsetX: 22.6, additionalOffsetY: 40, width: 3 };
            case "110,010,010": // L形 270°
                return { type: TetrisType.L, rotation: 270, isValid: true, shapeName: "L-Left", additionalOffsetX: 0.1, additionalOffsetY: 90, width: 2 };

            // O形方块 - 1种独特形状（所有旋转状态相同）
            case "11,11": // O形 所有角度
                return { type: TetrisType.O, rotation: 0, isValid: true, shapeName: "O-Square", additionalOffsetX: 32.5, additionalOffsetY: 37.5, width: 2 };

            // S形方块 - 2种独特形状
            case "011,110,000": // S形 0°/180°
                return { type: TetrisType.S, rotation: 0, isValid: true, shapeName: "S-Horizontal", additionalOffsetX: 23.5, additionalOffsetY: 0, width: 3 };
            case "010,011,001": // S形 90°/270°
                return { type: TetrisType.S, rotation: 90, isValid: true, shapeName: "S-Vertical", additionalOffsetX: 65.3, additionalOffsetY: 37.5, width: 2 };

            // T形方块 - 4种独特形状
            case "010,111,000": // T形 0°
                return { type: TetrisType.T, rotation: 0, isValid: true, shapeName: "T-Standard", additionalOffsetX: 23.5, additionalOffsetY: 0, width: 3 };
            case "010,011,010": // T形 90°
                return { type: TetrisType.T, rotation: 90, isValid: true, shapeName: "T-Right", additionalOffsetX: 46.7, additionalOffsetY: 50, width: 2 };
            case "000,111,010": // T形 180°
                return { type: TetrisType.T, rotation: 180, isValid: true, shapeName: "T-Inverted", additionalOffsetX: 41.3, additionalOffsetY: 37.5, width: 3 };
            case "010,110,010": // T形 270°
                return { type: TetrisType.T, rotation: 270, isValid: true, shapeName: "T-Left", additionalOffsetX: 0.1, additionalOffsetY: 50, width: 2 };

            // Z形方块 - 2种独特形状
            case "110,011,000": // Z形 0°/180°
                return { type: TetrisType.Z, rotation: 0, isValid: true, shapeName: "Z-Horizontal", additionalOffsetX: 32.5, additionalOffsetY: 0, width: 3 };
            case "001,011,010": // Z形 90°/270°
                return { type: TetrisType.Z, rotation: 90, isValid: true, shapeName: "Z-Vertical", additionalOffsetX: 55.3, additionalOffsetY: 30, width: 2 };

            // 未识别的形状
            default:
                return {
                    type: TetrisType.I,
                    rotation: 0,
                    isValid: false,
                    shapeName: "Unknown",
                    additionalOffsetX: 0,
                    additionalOffsetY: 0,
                    width: 0
                };
        }
    }

    /**
     * 获取所有独特的形状变体（去除重复）
     * @returns 所有独特形状的数组
     */
    public static getAllUniqueShapes(): ShapeIdentification[] {
        return [
            // I形方块 - 2种独特形状
            { type: TetrisType.I, rotation: 0, isValid: true, shapeName: "I-Horizontal", additionalOffsetX: 0, additionalOffsetY: 0, width: 4 },
            { type: TetrisType.I, rotation: 90, isValid: true, shapeName: "I-Vertical", additionalOffsetX: 0, additionalOffsetY: 0, width: 1 },
            
            // J形方块 - 4种独特形状
            { type: TetrisType.J, rotation: 0, isValid: true, shapeName: "J-Standard", additionalOffsetX: 0, additionalOffsetY: 0, width: 3 },
            { type: TetrisType.J, rotation: 90, isValid: true, shapeName: "J-Right", additionalOffsetX: 0, additionalOffsetY: 0, width: 2 },
            { type: TetrisType.J, rotation: 180, isValid: true, shapeName: "J-Inverted", additionalOffsetX: 0, additionalOffsetY: 0, width: 3 },
            { type: TetrisType.J, rotation: 270, isValid: true, shapeName: "J-Left", additionalOffsetX: 0, additionalOffsetY: 0, width: 2 },
            
            // L形方块 - 4种独特形状
            { type: TetrisType.L, rotation: 0, isValid: true, shapeName: "L-Standard", additionalOffsetX: 0, additionalOffsetY: 0, width: 3 },
            { type: TetrisType.L, rotation: 90, isValid: true, shapeName: "L-Right", additionalOffsetX: 0, additionalOffsetY: 0, width: 2 },
            { type: TetrisType.L, rotation: 180, isValid: true, shapeName: "L-Inverted", additionalOffsetX: 0, additionalOffsetY: 0, width: 3 },
            { type: TetrisType.L, rotation: 270, isValid: true, shapeName: "L-Left", additionalOffsetX: 0, additionalOffsetY: 0, width: 2 },
            
            // O形方块 - 1种独特形状
            { type: TetrisType.O, rotation: 0, isValid: true, shapeName: "O-Square", additionalOffsetX: 0, additionalOffsetY: 0, width: 2 },
            
            // S形方块 - 2种独特形状
            { type: TetrisType.S, rotation: 0, isValid: true, shapeName: "S-Horizontal", additionalOffsetX: 0, additionalOffsetY: 0, width: 3 },
            { type: TetrisType.S, rotation: 90, isValid: true, shapeName: "S-Vertical", additionalOffsetX: 0, additionalOffsetY: 0, width: 2 },
            
            // T形方块 - 4种独特形状
            { type: TetrisType.T, rotation: 0, isValid: true, shapeName: "T-Standard", additionalOffsetX: 0, additionalOffsetY: 0, width: 3 },
            { type: TetrisType.T, rotation: 90, isValid: true, shapeName: "T-Right", additionalOffsetX: 0, additionalOffsetY: 0, width: 2 },
            { type: TetrisType.T, rotation: 180, isValid: true, shapeName: "T-Inverted", additionalOffsetX: 0, additionalOffsetY: 0, width: 3 },
            { type: TetrisType.T, rotation: 270, isValid: true, shapeName: "T-Left", additionalOffsetX: 0, additionalOffsetY: 0, width: 2 },
            
            // Z形方块 - 2种独特形状
            { type: TetrisType.Z, rotation: 0, isValid: true, shapeName: "Z-Horizontal", additionalOffsetX: 0, additionalOffsetY: 0, width: 3 },
            { type: TetrisType.Z, rotation: 90, isValid: true, shapeName: "Z-Vertical", additionalOffsetX: 0, additionalOffsetY: 0, width: 2 }
        ];
    }

    /**
     * 获取指定类型的所有旋转状态
     * @param tetrisType 方块类型
     * @returns 该类型所有旋转状态的数组
     */
    public static getRotationsForType(tetrisType: TetrisType): ShapeIdentification[] {
        const allShapes = this.getAllUniqueShapes();
        return allShapes.filter(shape => shape.type === tetrisType);
    }

    /**
     * 检查两个形状是否相同
     * @param shape1 形状1
     * @param shape2 形状2
     * @returns 是否相同
     */
    public static areShapesEqual(shape1: number[][], shape2: number[][]): boolean {
        if (!shape1 || !shape2) return false;
        if (shape1.length !== shape2.length) return false;
        
        for (let i = 0; i < shape1.length; i++) {
            if (shape1[i].length !== shape2[i].length) return false;
            for (let j = 0; j < shape1[i].length; j++) {
                if (shape1[i][j] !== shape2[i][j]) return false;
            }
        }
        return true;
    }

    /**
     * 将形状矩阵转换为字符串用于比较
     * @param shape 形状矩阵
     * @returns 形状的字符串表示
     */
    private static shapeToString(shape: number[][]): string {
        return shape.map(row => row.join('')).join(',');
    }

    /**
     * 获取形状的可视化表示
     * @param shape 形状矩阵
     * @returns 可视化字符串
     */
    public static visualizeShape(shape: number[][]): string {
        if (!shape || shape.length === 0) return "Empty Shape";
        
        return shape.map(row => 
            row.map(cell => cell === 1 ? '■' : '□').join(' ')
        ).join('\n');
    }

    /**
     * 获取形状统计信息
     * @returns 形状统计信息
     */
    public static getShapeStatistics(): {
        totalUniqueShapes: number;
        shapesByType: { [key: string]: number };
        duplicateReduction: string;
    } {
        const uniqueShapes = this.getAllUniqueShapes();
        const shapesByType: { [key: string]: number } = {};
        
        // 统计每种类型的形状数量
        uniqueShapes.forEach(shape => {
            const typeName = TetrisType[shape.type];
            shapesByType[typeName] = (shapesByType[typeName] || 0) + 1;
        });

        return {
            totalUniqueShapes: uniqueShapes.length,
            shapesByType,
            duplicateReduction: `从28种变体减少到${uniqueShapes.length}种独特形状`
        };
    }
}