    public static itemListHandler(clip: Laya.Clip, index: number): void {
        let data: any[] = clip.dataSource;
        let _index: number = data[0];
        let _level: number = data[1];
        let _type: number = 2;
        let _clipSkin: string = clip.skin;
        if (_clipSkin) {
            if (_clipSkin.indexOf("xinSmall") != -1) {
                _type = 1;
            } else if (_clipSkin.indexOf("xinBig") != -1) {
                _type = 3;
            }
        }
        let _starStr: string;
        if (_type == 1) {
            _starStr = "common/common_clip/clip_xinSmall" + _level + ".png";
        } else if (_type == 3) {
            _starStr = "common/common_clip/clip_xinBig" + _level + ".png";
        } else {
            _starStr = "common/common_clip/clip_xinMiddle" + _level + ".png";
        }
        clip.skin = _starStr;
        clip.dataSource = _index;
    }
