const { regClass } = Laya;
import GameResourceManager from "../../common/GameResourceManager";
import { TimeUtil } from "../../utils/TimeUtil";
import { AssetNewScene } from "./AssetNewScene";
import { WithDrawRecordListItemBase } from "./WithDrawRecordListItem.generated";
import {getStatusKeyByValue } from "./AssetStatusEnum";

@regClass('tbS8gPlOTWuMdXb9g8wZAg==')
export class WithDrawRecordListItem extends WithDrawRecordListItemBase {
    public constructor() {
        super();
    }

    public set dataSource(data: any) {
        super.dataSource = data;
        if (!data) {
            this.visible = false;
            return;
        }

        const recordData = JSON.parse(data);
        const { createTime, symbolId, amount, status, symbol} = recordData;
        const { date, time } = TimeUtil.formatDayAndTime(createTime);

        this.tf_time.text = `${date}  ${time}`;
        this.img_coin.skin = GameResourceManager.getCurrencyIcon(symbol)
        this.tf_amounte.text = `${amount}`;
        this.tf_token.text = `${recordData.symbol}`;
        // console.log("withDrawStatus",status)
        this.tf_status.text = getStatusKeyByValue(status);
        // 获取IsDepositRecord
        this.tf_operate.text = AssetNewScene.isDepositRecord ? "Deposit" : "Withdraw";

        // 获取当前项在列表中的索引位置，用于控制背景显示
        const index = (this.parent?.parent as Laya.List)?.array?.indexOf(data) ?? 0;

        // 奇数行显示背景，偶数行不显示
        this.img_bg.skin = index % 2 === 1 ? "res/asset/assetNew/img_di1.png" : "res/asset/assetNew/img_di.png";
    }
}
