const { regClass } = Laya;
import GameResourceManager from "../../common/GameResourceManager";
import AssetManager from "../../manager/AssetManager";
import { com } from "../../network/pb/socket";
import { ComUtil } from "../../utils/ComUtil";
import { NumberUtil } from "../../utils/NumberUtil";
import { TimeUtil } from "../../utils/TimeUtil";
import { MatchTournamentRankListItemBase } from "./MatchTournamentRankListItem.generated";

@regClass('9g9PPJvzQcGLbhD4OsMd7g==')
export class MatchTournamentRankListItem extends MatchTournamentRankListItemBase {
    public constructor() {
        super();
    }
    onEnable(): void {}

    public set dataSource(value: com.snake.socket.RankObject) {
        super.dataSource = value;
        if (!value) {
            this.visible = false;
            return;
        }

        this.PlayerIcon.dataSource = value;
        this.tf_name.text = ComUtil.fitTextToLabel(value.userName, this.tf_name);

        // // 获取当前项在列表中的索引位置，用于控制背景显示
        // const index = (this.parent?.parent as Laya.List)?.array?.indexOf(value) ?? 0;

        // // 奇数行显示背景，偶数行不显示
        // this.img_bg.visible = index % 2 === 1;

        // this.tf_rank.text = `${index + 1}`;

        this.tf_rank.text = `${value.rank}`;

        this.img_flag.skin = GameResourceManager.getCountryIconById(value.country);

        var extra = value.extra;
        if (extra) {
            var extraData = extra.split(","); //比赛次数，击杀数，积分，时长，token，数量
            this.tf_killCount.text = extraData[1];
            this.tf_foodScore.text = value.num + "";// extraData[2];
            this.tf_liveTime.text = TimeUtil.format(parseFloat(extraData[3]));
            var symbolId = extraData[4];
            var reward = NumberUtil.filterNumFormat(extraData[5],4,false,true);

            //奖池显示
            let tokenData = AssetManager.getTokenDataBySyId(Number(symbolId));
            if (tokenData) {
                this.tf_reward.text = `${reward} ${tokenData.symbol}`;
            } else {
                this.tf_reward.text = `${reward}`;
            }
        }

        // //前三名显示img_title；
        // //前三名的背景显示img_b1,img_b2,img_b3
        // if (index < 3) {
        //     this.img_title.visible = true;
        //     this.tf_rank.visible = false;
        //     this.img_title.skin = `res/rank/img_b${index + 1}.png`;
        // } else {
        //     this.img_title.visible = false;
        //     this.tf_rank.visible = true;
        // }

        // // img_title
    }
}
