import { BaseItem } from "../BaseItem";
export class ClubItem extends BaseItem {
    public id: number; // id
    public name: number; // 俱乐部名称ID
    public price: number; // 价格
    public maxMember: number; // 最大成员数
    public maxRoom: number; // 最大房间数
    public dailyRoom: number; // 每日房间数
    public weeklyRoom: number; // 每周房间数
    public ownerCommission: number; // 拥有者佣金比例
    public referalCommission: number; // 推荐佣金比例
    public fightReward: number; // 战斗奖励
}
