const { regClass } = Laya;
import { ClubHeadListItemBase } from "./ClubHeadListItem.generated";

@regClass('uklnPq1ZQmOhfyUyF/6oWQ==')
export class ClubHeadListItem extends ClubHeadListItemBase {
    private headItem: number;
    public set dataSource(value: number) {
        super.dataSource = value;
        this.headItem = value;
        if (!this.headItem) {
            return;
        }
        this.setCurrentOutPut();
    }

    async setCurrentOutPut() {
        let headId = this.headItem;
        this.clubBigIcon.headSkin = headId;
    }
    onChange(isSelect: boolean) { }
}
