import { Quick } from "../utils/Quick";
import { com } from "./pb/socket";
import { SocketDataUtil } from "../utils/SocketDataUtil";
import MatchModel from "../modules/match/MatchModel";
import { RoomMessageHandle } from "./RoomMessageHandle";
import Signal from "../global/event/Signal";
import { SocketEvent } from "../global/event/SocketEvent";
import GlobalDataManager from "../global/GlobalDataManager";
import GameSetting from "../global/GameSetting";

class RoomWebSocket {
    public m_strHttpHost: string = getWSServer();
    public _socket: Laya.Socket;
    private connected: boolean;
    isOtherLogin: boolean;
    serverTimeOffset = 0; // 客户端与服务端的时间差
    serverTimeOffsets: number[] = []; // 客户端与服务端的时间差数组
    delaT = 0; // 预估发送到服务器的时长
    delaTs: number[] = []; // 预估发送到服务器的时长数组
    _lastRTT: number = 0; // 最后一次测量的往返延迟

    // 字节缓存
    private _byte: Laya.Byte;
    // 包头长度
    private _headerLength = 4;
    // 当前正在处理的数据包长度
    private _packetLength: number = -1;
    // handle: RoomMessageHandle;

    public constructor() {
        new RoomMessageHandle();
        this._byte = new Laya.Byte();
        this._byte.endian = "bigEndian"; // "littleEndian";根据实际协议调整
        this._socket = new Laya.Socket();
        this._socket.on(Laya.Event.OPEN, this, this.onSocketOpen);
        this._socket.on(Laya.Event.CLOSE, this, this.onSocketClose);
        this._socket.on(Laya.Event.MESSAGE, this, this.onMessageReveived);
        this._socket.on(Laya.Event.ERROR, this, this.onConnectError);
    }
    private static _instance: RoomWebSocket;
    public static getInstance(): RoomWebSocket {
        if (RoomWebSocket._instance == null) {
            RoomWebSocket._instance = new RoomWebSocket();
        }
        return RoomWebSocket._instance;
    }
    
    // 添加静态方法获取连接状态
    public getIsConnect(): boolean {
        if (RoomWebSocket._instance == null) {
            return false;
        }
        return RoomWebSocket._instance.connected;
    }
    
    private _isMatching: boolean = false;
    public get isMatching(): boolean {
        return this._isMatching;
    }
    public set isMatching(value: boolean) {
        this._isMatching = value;
        if (!value) {
            // this.m_socket.close();//比赛结束 主动关闭socket
            this.connected = false;
        }
    }

    close() {
        if (this._socket) {
            this._socket.close();
        }
        this.emit(SocketEvent.EVENT_ROOM_STOP_HEART);
    }

    public closeConnect() {
        this.isMatching = false; //比赛结束不再使用socket
        this.emit(SocketEvent.EVENT_ROOM_HIDE_TIP_DELAY);

        this.close();
    }

    public initSocket(): void {
        this.isMatching = true;

        //正式环境启用
        // var ws = "ws://175.27.154.72:10011";
        // console.log("GlobalDataManager.nodeId===============>", GlobalDataManager.nodeItem);

        //从SheetDataManager.m_dicNodes.values中找到对应的nodeId的item
        let nodeItem = GlobalDataManager.nodeItem;

        //获取到对应item的socketUrl
        let socketUrl = null;
        if (nodeItem && nodeItem.socketUrl) {
            socketUrl = nodeItem.socketUrl;
        }

        //如果没有nodeId或者没有item,ws就设置为默认的MatchModel.roomDto.connectAddr
        //否则就设置为item的socketUrl

        var ws = socketUrl;
        if (MatchModel.roomDto && MatchModel.roomDto.connectAddr) {//如果是俱乐部进入或者观看进入，读取对应房间号的地址
            ws = MatchModel.roomDto.connectAddr;
        }
        if (GameSetting.roomUrlTest) {//如果url设置了socket，就设置为roomUrlTest

            this.m_strHttpHost = GameSetting.roomUrlTest;
        } else {
            this.m_strHttpHost = ws;
        }
        this.connect();
    }

    /**
     * 连接成功
     */
    public onSocketOpen(): void {
        this.connected = true;
        console.log(Quick.GetLogTime, "[RoomWebSocket] ----onOpen------------> connected");
        this.emit(SocketEvent.EVENT_ROOM_SOCKET_OPEN);
    }
    public onConnectError(e: any): void {
        this.connected = false;
        console.log(Quick.GetLogTime, "[RoomWebSocket] ----onError------------>", e);
        this.emit(SocketEvent.EVENT_ROOM_SOCKET_ERROR);
    }
    public onSocketClose(e: any): void {
        this.connected = false;
        console.log(Quick.GetLogTime, "[RoomWebSocket] ----onClose------------>", this._socket);
        this.emit(SocketEvent.EVENT_ROOM_SOCKET_CLOSE);
    }

    private connect() {
        console.log(Quick.GetLogTime, "[RoomWebSocket] connect: " + this.m_strHttpHost, 1);
        if (!this.isMatching) {
            return; //不在比赛中
        }
        if (this.connected) {
            return; //连接了
        }

        this._socket.connectByUrl(this.m_strHttpHost);
        this.emit(SocketEvent.EVENT_ROOM_SHOW_TIP_DELAY);
    }

    public sendData(messageType: number, body?: any, need: boolean = true): void {
        // if (!this.isMatching && need) {
        //     return; //不在比赛中，不用使用
        // }

        if (this.connected) {
            var byteData: Uint8Array = body ? body.serializeBinary() : null;
            // if (GameSetting.Debug != 0) {
            console.log(Quick.GetLogTime, "[RoomWebSocket]  ------>>>>>>>> SEND CMD:" + messageType, body ? body.toObject() : null);
            // }

            var data = SocketDataUtil.encodeMessage(messageType, byteData, "");
            this._socket.send(data.buffer);
        } else {
            // console.log(Quick.GetLogTime, "[RoomWebSocket]  ------>>>>>>>> SENDE RROR CMD:" + messageType, body ? body.toObject() : null);
        }
    }

    async onMessageReveived(msg: ArrayBuffer) {
        if (!(msg instanceof ArrayBuffer)) {
            console.warn(Quick.GetLogTime, "[RoomWebSocket]: no ArrayBuffer data", msg);
            return;
        }
        console.log(Quick.GetLogTime, "[RoomWebSocket]: onMessage", msg.byteLength);

        // 将新数据追加到缓存
        let newData = new Uint8Array(msg);
        this._byte.writeArrayBuffer(newData.buffer);
        this._byte.pos = 0;

        // 处理数据包
        while (this._byte.bytesAvailable > 0) {
            if (this._packetLength === -1) {
                // 读取包头获取包体长度
                if (this._byte.bytesAvailable >= this._headerLength) {
                    this._packetLength = this._byte.getUint32();
                } else {
                    break; // 数据不足，等待更多数据
                }
            }

            // 检查是否有完整的包体
            if (this._byte.bytesAvailable >= this._packetLength) {
                // 读取包体数据
                let packetData = this._byte.readUint8Array(this._headerLength, this._packetLength);
                this.processPacket(packetData);
                this._packetLength = -1; // 重置准备读取下一个包头
            } else {
                break; // 数据不足，等待更多数据
            }
        }

        // 清理已处理的数据
        if (this._byte.pos > 0) {
            let remaining = this._byte.bytesAvailable;
            if (remaining > 0) {
                let temp = this._byte.readUint8Array(0, remaining);
                this._byte.clear();
                this._byte.writeArrayBuffer(temp.buffer);
            } else {
                this._byte.clear();
            }
        }
    }

    /**
     * 处理完整的数据包
     * @param data 数据包内容(Uint8Array)
     */
    private processPacket(data: Uint8Array): void {
        try {
            var messageBase = SocketDataUtil.decodeMessage(data);
            // var messageBase = com.snake.socket.CMsgBase.deserializeBinary(data);
            var msgtype = messageBase.msghead.msgtype;

            // console.log(Quick.GetLogTime, "[RoomWebSocket]: onMessage", msgtype.toString(), messageBase);
            this.emitter(msgtype, messageBase);
        } catch (e) {
            // console.log(Quick.GetLogTime, "[RoomWebSocket] onSocketError e:" + e);
        }
    }

    emitter(msgtype: number, messageBase: com.snake.socket.CMsgBase) {
        var msgcode = messageBase.msghead.msgcode;
        if (msgcode != com.snake.socket.MessageCode.SYS_NORMAL) {
            this.emit(SocketEvent.EVENT_GLOBAL_ERROR_CODE, msgcode);
        }
        if (msgtype != com.snake.socket.MessageType.MSG_HEART_BEAT) {
            this.emit("msg_" + msgtype, messageBase, msgcode);
        } else {
            this.emit(SocketEvent.EVENT_ROOM_HEART_BEAT, messageBase, msgcode);
        }
    }

    /**
     * 触发事件
     * @param event 事件名称
     * @param args 参数
     */
    private emit(event: string, ...args: any[]): void {
        Signal.event(event, args);
    }
    // 新增调试方法
    public logLatencyStats(): void {
        console.log(`[FrameSync] 当前平滑延迟: ${this.delaT.toFixed(1)}ms, 最新RTT: ${this._lastRTT}ms`);
    }
    public clearAll() {
        Laya.timer.clearAll(this);
        this.close();
        
    }
}
export default RoomWebSocket.getInstance();
