import { AlertType } from "./AlertType";
import { ModuleManager } from "./ModuleManager";

class AlertManager {
    private static _instance: AlertManager;
    public constructor() {}

    public static getInstance(): AlertManager {
        if (!AlertManager._instance) {
            AlertManager._instance = new AlertManager();
        }
        return AlertManager._instance;
    }

    public AlertByType(
        type: string,
        data: any = null,
        flag: number = 0,
        okHandler: Laya.Handler = null,
        cancelHandler: Laya.Handler = null,
        destroyDoCancel: boolean = false,
        initHandler: Laya.Handler = null,
        canClose = true,
        canCloseBySide = true
    ): void {
        if (flag == 0) {
            flag = AlertType.YES | AlertType.NO;
        }
        this.onLoaded(flag, type, data, okHandler, cancelHandler, destroyDoCancel, initHandler, canClose, canCloseBySide);
    }

    private onLoaded(
        flag: number,
        type: string,
        data: any,
        okHandler: Laya.Handler = null,
        cancelHandler: Laya.Handler = null,
        destroyDoCancel: boolean = false,
        initHandler: Laya.Handler = null,
        canClose = true,
        canCloseBySide = true
    ): void {
        ModuleManager.intance.openModule(type, { flag, okHandler, cancelHandler, data, destroyDoCancel, initHandler, canClose, canCloseBySide });
    }
}
export default AlertManager.getInstance();
