const { regClass } = Laya;
import GameLanguageMgr from "../../common/GameLanguageMgr";
import { LayerManager } from "../../common/LayerManager";
import { ModuleManager } from "../../common/ModuleManager";
import { ItemItem } from "../../data/sheetItem/item/ItemItem";
import { GameEvent } from "../../global/event/GameEvent";
import Signal from "../../global/event/Signal";
import KnapsackManager from "../../global/KnapsackManager";
import { ModuleName } from "../../global/ModuleName";
import SheetDataManager from "../../global/SheetDataManager";
import { com } from "../../network/pb/socket";
import HallWebSocket from "../../network/HallWebSocket";
import { SnakeUpgradeDialogBase } from "./SnakeUpgradeDialog.generated";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import SoundMgr from "../../common/SoundMgr";
import GameResourceManager from "../../common/GameResourceManager";
import { SnakeVo } from "../../data/vo/pack/SnakeVo";


@regClass('K6ZKHKhaTvCBmQcFdrneHQ==')
export class SnakeUpgradeDialog extends SnakeUpgradeDialogBase {
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;
    public nftItem: SnakeVo;

    public constructor() {
        super();
    }

    onEnable(): void {
        this.backLayer.alpha = 0;
        this.backLayer.visible = true;
        Laya.Tween.to(this.backLayer, { alpha: 1 }, 200, Laya.Ease.linearIn);
        this.btn_upgrade.on(Laya.Event.CLICK, this, this.onUpdateClick);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_SNAKE_UPGRADE, this, this.onUpgradeCallback);
    }

    /**
     * 显示购买页信息
     * @param data
     */
    public setOpenData(data: SnakeVo) {
        if (data) {
            this.nftItem = data as SnakeVo;
            this.initProp();
        }
    }

    private initProp() {
        const needProp = [1201, 1202, 1203, 1204, 1205];
        let hasEnough = true;
        for (let i = 0; i < needProp.length; i++) {
            const propItem: ItemItem = SheetDataManager.m_dicItems.get(needProp[i]);
            if (propItem) {
                const prop = (this as any)["item_" + i];
                if (prop) {
                    let tf_name = prop.getChildByName("tf_name") as Laya.Label;
                    let img_icon = prop.getChildByName("img_icon") as Laya.Image;
                    // 数量
                    const num = KnapsackManager.getKnapsackItemCount(needProp[i]);
                    tf_name.text = `${GameLanguageMgr.getLanguage(propItem.name)} x${num}`;
                    img_icon.skin = GameResourceManager.getItemIcon(propItem);
                    console.log("num", num);
                    // 检查数量是否小于5个
                    if (num < 5) {
                        hasEnough = false;
                        // 如果数量不足5个，文本变灰
                        prop.gray = true;
                    } else {
                        // 数量足够，文本保持正常颜色
                        prop.gray = false;
                    }
                }
            }
        }
        // 设置升级按钮的禁用状态
        this.btn_upgrade.disabled = !hasEnough;
    }

    onUpdateClick() {
        const cmdId = com.snake.socket.MessageType.MSG_SNAKE_UPGRADE;
        const requestData = com.snake.socket.CS_SNAKE_UPGRADE.fromObject({
            unkey: this.nftItem.unkey
        });
        HallWebSocket.send(cmdId, requestData);
    }

    private onUpgradeCallback(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_SNAKE_UPGRADE = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_SNAKE_UPGRADE);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            // 购买成功回调
            // 升级成功音效
            SoundMgr.playSoundByName(SoundMgr.soundName_snakeUpdate);
            if (msgBody) {
                Signal.event(GameEvent.UPDATE_BAG_INFO);
                ModuleManager.intance.openModule(ModuleName.SnakeUpgradeSuccessDialog, msgBody);
            }
            // 发送获取背包信息请求
            const cmdId = com.snake.socket.MessageType.MSG_PACK_INFO;
            HallWebSocket.send(cmdId);
            this.close();
        }
    }

    onDisable(): void {
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_SNAKE_UPGRADE, this, this.onUpgradeCallback);
    }
}
