export class ByteEx {
    public static BIG_ENDIAN: string = "bigEndian";
    public static LITTLE_ENDIAN: string = "littleEndian";
    private static _sysEndian: string = null;
    protected _xd_: boolean = true;
    private _allocated_: number = 8;
    protected _d_: any;
    protected _u8d_: any;
    protected _pos_: number = 0;
    protected _length: number = 0;

    public static getSystemEndian(): string {
        if (!ByteEx._sysEndian) {
            let buffer: any = new ArrayBuffer(2);
            new DataView(buffer).setInt16(0, 256, true);
            ByteEx._sysEndian = new Int16Array(buffer)[0] === 256 ? ByteEx.LITTLE_ENDIAN : ByteEx.BIG_ENDIAN;
        }
        return ByteEx._sysEndian;
    }

    public constructor(data: any = null) {
        if (data) {
            this._u8d_ = new Uint8Array(data);
            this._d_ = new DataView(this._u8d_.buffer);
            this._length = this._d_.byteLength;
        } else {
            this._resizeBuffer(this._allocated_);
        }
    }

    public get buffer(): ArrayBuffer {
        let rstBuffer: ArrayBuffer = this._d_.buffer;
        if (rstBuffer.byteLength === this._length) {
            return rstBuffer;
        }
        return rstBuffer.slice(0, this._length);
    }

    public get endian(): string {
        return this._xd_ ? ByteEx.LITTLE_ENDIAN : ByteEx.BIG_ENDIAN;
    }

    public set endian(value: string) {
        this._xd_ = value === ByteEx.LITTLE_ENDIAN;
    }

    public set length(value: number) {
        if (this._allocated_ < value) {
            this._resizeBuffer((this._allocated_ = Math.floor(Math.max(value, this._allocated_ * 2))));
        } else if (this._allocated_ > value) {
            this._resizeBuffer((this._allocated_ = value));
        }
        this._length = value;
    }

    public get length(): number {
        return this._length;
    }

    private _resizeBuffer(len: number): void {
        try {
            let newByteView: any = new Uint8Array(len);
            if (this._u8d_ != null) {
                if (this._u8d_.length <= len) {
                    newByteView.set(this._u8d_);
                } else {
                    newByteView.set(this._u8d_.subarray(0, len));
                }
            }
            this._u8d_ = newByteView;
            this._d_ = new DataView(newByteView.buffer);
        } catch (err) {
            throw "Invalid typed array length:" + len;
        }
    }

    public getString(): string {
        return this.readString();
    }

    public readString(): string {
        return this._rUTF(this.getUint16());
    }

    public getFloat32Array(start: number, len: number): any {
        return this.readFloat32Array(start, len);
    }

    public readFloat32Array(start: number, len: number): any {
        let end: number = start + len;
        end = end > this._length ? this._length : end;
        let v: any = new Float32Array(this._d_.buffer.slice(start, end));
        this._pos_ = end;
        return v;
    }

    public getUint8Array(start: number, len: number): Uint8Array {
        return this.readUint8Array(start, len);
    }

    public readUint8Array(start: number, len: number): Uint8Array {
        let end: number = start + len;
        end = end > this._length ? this._length : end;
        let v: any = new Uint8Array(this._d_.buffer.slice(start, end));
        this._pos_ = end;
        return v;
    }

    public getInt16Array(start: number, len: number): any {
        return this.readInt16Array(start, len);
    }

    public readInt16Array(start: number, len: number): any {
        let end: number = start + len;
        end = end > this._length ? this._length : end;
        let v: any = new Int16Array(this._d_.buffer.slice(start, end));
        this._pos_ = end;
        return v;
    }

    public getFloat32(): number {
        return this.readFloat32();
    }

    public readFloat32(): number {
        if (this._pos_ + 4 > this._length) {
            throw "getFloat32 error - Out of bounds";
        }
        let v: number = this._d_.getFloat32(this._pos_, this._xd_);
        this._pos_ += 4;
        return v;
    }

    public getFloat64(): number {
        return this.readFloat64();
    }

    public readFloat64(): number {
        if (this._pos_ + 8 > this._length) {
            throw "getFloat64 error - Out of bounds";
        }
        let v: number = this._d_.getFloat64(this._pos_, this._xd_);
        this._pos_ += 8;
        return v;
    }

    public writeFloat32(value: number): void {
        this._ensureWrite(this._pos_ + 4);
        this._d_.setFloat32(this._pos_, value, this._xd_);
        this._pos_ += 4;
    }

    public writeFloat64(value: number): void {
        this._ensureWrite(this._pos_ + 8);
        this._d_.setFloat64(this._pos_, value, this._xd_);
        this._pos_ += 8;
    }

    public getInt32(): number {
        return this.readInt32();
    }

    public readInt32(): number {
        if (this._pos_ + 4 > this._length) {
            throw "getInt32 error - Out of bounds";
        }
        let float: number = this._d_.getInt32(this._pos_, this._xd_);
        this._pos_ += 4;
        return float;
    }

    public getUint32(): number {
        return this.readUint32();
    }

    public readUint32(): number {
        if (this._pos_ + 4 > this._length) {
            throw "getUint32 error - Out of bounds";
        }
        let v: number = this._d_.getUint32(this._pos_, this._xd_);
        this._pos_ += 4;
        return v;
    }

    public writeInt32(value: number): void {
        this._ensureWrite(this._pos_ + 4);
        this._d_.setInt32(this._pos_, value, this._xd_);
        this._pos_ += 4;
    }

    public writeUint32(value: number): void {
        this._ensureWrite(this._pos_ + 4);
        this._d_.setUint32(this._pos_, value, this._xd_);
        this._pos_ += 4;
    }

    public getInt16(): number {
        return this.readInt16();
    }

    public readInt16(): number {
        if (this._pos_ + 2 > this._length) {
            throw "getInt16 error - Out of bounds";
        }
        let us: number = this._d_.getInt16(this._pos_, this._xd_);
        this._pos_ += 2;
        return us;
    }

    public getUint16(): number {
        return this.readUint16();
    }

    public readUint16(): number {
        if (this._pos_ + 2 > this._length) {
            throw "getUint16 error - Out of bounds";
        }
        let us: number = this._d_.getUint16(this._pos_, this._xd_);
        this._pos_ += 2;
        return us;
    }

    public writeUint16(value: number): void {
        this._ensureWrite(this._pos_ + 2);
        this._d_.setUint16(this._pos_, value, this._xd_);
        this._pos_ += 2;
    }

    public writeInt16(value: number): void {
        this._ensureWrite(this._pos_ + 2);
        this._d_.setInt16(this._pos_, value, this._xd_);
        this._pos_ += 2;
    }

    public getUint8(): number {
        return this.readUint8();
    }

    public readUint8(): number {
        if (this._pos_ + 1 > this._length) {
            throw "getUint8 error - Out of bounds";
        }
        return this._d_.getUint8(this._pos_++);
    }

    public writeUint8(value: number): void {
        this._ensureWrite(this._pos_ + 1);
        this._d_.setUint8(this._pos_, value);
        this._pos_++;
    }

    public _getUInt8(pos: number): number {
        return this._readUInt8(pos);
    }

    public _readUInt8(pos: number): number {
        return this._d_.getUint8(pos);
    }

    public _getUint16(pos: number): number {
        return this._readUint16(pos);
    }

    public _readUint16(pos: number): number {
        return this._d_.getUint16(pos, this._xd_);
    }

    public _getMatrix(): Laya.Matrix {
        return this._readMatrix();
    }

    public _readMatrix(): Laya.Matrix {
        let rst: Laya.Matrix = new Laya.Matrix(
            this.getFloat32(),
            this.getFloat32(),
            this.getFloat32(),
            this.getFloat32(),
            this.getFloat32(),
            this.getFloat32()
        );
        return rst;
    }

    private _rUTF(len: number): string {
        let v: string = "",
            max: number = this._pos_ + len,
            c: number,
            c2: number,
            c3: number,
            f: Function = String.fromCharCode;
        let u: any = this._u8d_,
            i: number = 0;
        while (this._pos_ < max) {
            c = u[this._pos_++];
            if (c < 0x80) {
                if (c != 0) {
                    v += f(c);
                }
            } else if (c < 0xe0) {
                v += f(((c & 0x3f) << 6) | (u[this._pos_++] & 0x7f));
            } else if (c < 0xf0) {
                c2 = u[this._pos_++];
                v += f(((c & 0x1f) << 12) | ((c2 & 0x7f) << 6) | (u[this._pos_++] & 0x7f));
            } else {
                c2 = u[this._pos_++];
                c3 = u[this._pos_++];
                v += f(((c & 0x0f) << 18) | ((c2 & 0x7f) << 12) | ((c3 << 6) & 0x7f) | (u[this._pos_++] & 0x7f));
            }
            i++;
        }
        return v;
    }

    public getCustomString(len: number): string {
        return this.readCustomString(len);
    }

    public readCustomString(len: number): string {
        let v: string = "",
            ulen: number = 0,
            c: number,
            c2: number,
            f: Function = String.fromCharCode;
        let u: any = this._u8d_,
            i: number = 0;
        while (len > 0) {
            c = u[this._pos_];
            if (c < 0x80) {
                v += f(c);
                this._pos_++;
                len--;
            } else {
                ulen = c - 0x80;
                this._pos_++;
                len -= ulen;
                while (ulen > 0) {
                    c = u[this._pos_++];
                    c2 = u[this._pos_++];
                    v += f((c2 << 8) | c);
                    ulen--;
                }
            }
        }
        return v;
    }

    public get pos(): number {
        return this._pos_;
    }

    public set pos(value: number) {
        this._pos_ = value;
    }

    public get bytesAvailable(): number {
        return this._length - this._pos_;
    }

    public clear(): void {
        this._pos_ = 0;
        this.length = 0;
    }

    public __getBuffer(): ArrayBuffer {
        return this._d_.buffer;
    }

    public writeUTFBytes(value: string): void {
        value = "" + value + " ";
        for (let i: number = 0, sz: number = value.length; i < sz; i++) {
            let c: number = value.charCodeAt(i);
            if (c <= 0x7f) {
                this.writeByte(c);
            } else if (c <= 0x7ff) {
                this._ensureWrite(this._pos_ + 2);
                this._u8d_.set([0xc0 | (c >> 6), 0x80 | (c & 0x3f)], this._pos_);
                this._pos_ += 2;
            } else if (c <= 0xffff) {
                this._ensureWrite(this._pos_ + 3);
                this._u8d_.set([0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f)], this._pos_);
                this._pos_ += 3;
            } else {
                this._ensureWrite(this._pos_ + 4);
                this._u8d_.set([0xf0 | (c >> 18), 0x80 | ((c >> 12) & 0x3f), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f)], this._pos_);
                this._pos_ += 4;
            }
        }
    }

    public writeUTFString(value: string): void {
        let tPos: number = this.pos;
        this.writeUint16(1);
        this.writeUTFBytes(value);
        let dPos: number = this.pos - tPos - 2;
        this._d_.setUint16(tPos, dPos, this._xd_);
    }

    public readUTFString(): string {
        return this.readUTFBytes(this.getUint16());
    }

    public getUTFString(): string {
        return this.readUTFString();
    }

    public readUTFBytes(len: number = -1): string {
        if (len === 0) {
            return "";
        }
        let lastBytes: number = this.bytesAvailable;
        if (len > lastBytes) {
            throw "readUTFBytes error - Out of bounds";
        }
        len = len > 0 ? len : lastBytes;
        return this._rUTF(len);
    }

    public getUTFBytes(len: number = -1): string {
        return this.readUTFBytes(len);
    }

    public writeByte(value: number): void {
        this._ensureWrite(this._pos_ + 1);
        this._d_.setInt8(this._pos_, value);
        this._pos_ += 1;
    }

    public readByte(): number {
        if (this._pos_ + 1 > this._length) {
            throw "readByte error - Out of bounds";
        }
        return this._d_.getInt8(this._pos_++);
    }

    public getByte(): number {
        return this.readByte();
    }

    public _ensureWrite(lengthToEnsure: number): void {
        if (this._length < lengthToEnsure) {
            this._length = lengthToEnsure;
        }
        if (this._allocated_ < lengthToEnsure) {
            this.length = lengthToEnsure;
        }
    }

    public writeArrayBuffer(arraybuffer: any, offset: number = 0, length: number = 0): void {
        if (offset < 0 || length < 0) {
            throw "writeArrayBuffer error - Out of bounds";
        }
        if (length == 0) {
            length = arraybuffer.byteLength - offset;
        }
        this._ensureWrite(this._pos_ + length);
        let uint8array: any = new Uint8Array(arraybuffer);
        this._u8d_.set(uint8array.subarray(offset, offset + length), this._pos_);
        this._pos_ += length;
    }
}
