const { regClass } = Laya;
import { LayerManager } from "../../common/LayerManager";
import { JoinRoomDialogBase } from "./JoinRoomDialog.generated";
import EnterRoomManager from "./EnterRoomManager";
import SheetDataManager from "../../global/SheetDataManager";
import { RoomItem } from "../../data/sheetItem/RoomItem";
import HallWebSocket from "../../network/HallWebSocket";
import { com } from "../../network/pb/socket";
import Signal from "../../global/event/Signal";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import GameResourceManager from "../../common/GameResourceManager";
import AssetManager from "../../manager/AssetManager";
import GameSetting from "../../global/GameSetting";
import { TokenData } from "../../data/dto/TokenData";
import { ModuleManager } from "../../common/ModuleManager";
import { ModuleName } from "../../global/ModuleName";
import { GameEvent } from "../../global/event/GameEvent";
import NoticeMgr from "../notice/NoticeMgr";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import GlobalDataManager from "../../global/GlobalDataManager";
import { NumberUtil } from "../../utils/NumberUtil";
import { Quick } from "../../utils/Quick";
import { DESTool } from "../../utils/DESTool";
import { EnumMatch } from "../../data/enumData/EnumMatch";

// Tab 相关常量定义
const TAB_COUNT = 3;
const TAB_SKINS = {
    selected: ["res/main/join/img_tbl1.png", "res/main/join/img_tbm1.png", "res/main/join/img_tbr1.png"],
    unselected: ["res/main/join/img_tbl2.png", "res/main/join/img_tbm2.png", "res/main/join/img_tbr2.png"]
};
const STROKE_COLORS = {
    selected: "#0c6917",
    unselected: "#405073"
};
const ROOM_TYPES = [2, 3, 4]; // 对应每个 tab 的房间类型
// localStorage 存储键
const STORAGE_KEY_TAB = "joinRoom_tabIndex";
const STORAGE_KEY_TOKEN = "joinRoom_tokenIndex";

@regClass('NM3GHDnJRD6AnD7XkkQaig==')
export class JoinRoomDialog extends JoinRoomDialogBase {
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;
    // private roomType: number;
    private roomItem: RoomItem;
    private roomData: RoomItem;
    private roomType: number;
    private tabIndex: number = 0;
    private tokenIndex: number = 0;
    private isEntering: boolean = false; // 添加进入对战状态标记
    private _isInitializing: boolean = true; // 标记是否是初始化阶段

    public constructor() {
        super();
    }
    /**
     * 显示购买页信息
     * @param data 参数
     */
    public setOpenData(data: any): void {
        this._isInitializing = true; // 标记为初始化阶段
        
        // 初始化事件和背景
        this.initEvents();
        GlobalDataManager.needToOpenJoinRoom = false;
        this.backLayer.alpha = 0;
        this.backLayer.visible = true;
        Laya.Tween.to(this.backLayer, { alpha: 0.7 }, 200, Laya.Ease.linearIn);
        
        // 优先级1：检查URL参数中是否有room信息
        const urlParams = new URLSearchParams(window.location.search);
        const roomParam = urlParams.get('room');
        let urlTabIndex = -1;
        let urlTokenIndex = -1;
        
        if (roomParam) {
            try {
                var _room = DESTool.decodeStr(roomParam);//base64解密
                const roomInfo = JSON.parse(decodeURIComponent(_room));
                const dic = SheetDataManager.m_dicRoom?.values;
                let roomType = ROOM_TYPES[roomInfo.tabIndex];

                const roomItems = dic.filter((item) => item.roomType == roomType && item.gameId == 100003);
                this.roomData = roomItems[0];
                const foundIndex = this.roomData.ticketType.findIndex((item) => item === roomInfo.tokenType);
                if (roomInfo.tabIndex !== undefined) urlTabIndex = roomInfo.tabIndex;
                if (foundIndex !== undefined) urlTokenIndex = foundIndex
                console.log("从URL参数获取房间信息:", roomInfo);
                
                // 清除URL参数，防止刷新页面时重复打开
                if (window.history && window.history.replaceState) {
                    // 获取当前URL
                    const currentUrl = new URL(window.location.href);
                    // 只删除room参数，保留其他参数
                    currentUrl.searchParams.delete('room');
                    // 更新URL，不改变其他参数
                    window.history.replaceState({}, document.title, currentUrl.toString());
                }
            } catch (error) {
                console.error("解析URL房间参数失败:", error);
            }
        }

            // 优先级2：从localStorage获取存储的值
            const savedTabIndex = this.getSavedTabIndex();
            const savedTokenType = this.getSavedTokenType();
            // 按优先级设置最终值
            const defaultTabIndex = (data && data[0] !== undefined) ? data[0] : 0;
            this.tabIndex = (urlTabIndex !== -1) ? urlTabIndex : 
                            (savedTabIndex !== null) ? savedTabIndex : defaultTabIndex;
            var defaultTokenIndex = -1;

            if(urlTokenIndex !== -1) {
                defaultTokenIndex = urlTokenIndex;
            } else if(savedTokenType !== null) {
                defaultTokenIndex = this.getTokenIndexByTabIndexAndTokenType(defaultTabIndex, savedTokenType);
            }else{
                defaultTokenIndex = (data && data[1] !== undefined) ? data[1] : 0;
            }
            // 优先级3：使用传入的默认值
            

                            
            this.tokenIndex = defaultTokenIndex;
        
        // if (!AssetManager.getTokenData()) {
            this.requestCoinInfo();
        // } else {
        //     this.onTabClick(this.tabIndex);
        // }
    }

        getTokenIndexByTabIndexAndTokenType(tabIndex: number, tokenType: number): number {
        var roomType: number;
            // 设置当前房间类型
        roomType = ROOM_TYPES[tabIndex];
        
        const dic = SheetDataManager.m_dicRoom?.values;
        const roomItems = dic.filter((item) => item.roomType == roomType);

        if (roomItems.length === 0) return -1;

        // 根据ticketType去重
        var roomItem = roomItems[0];
        if (roomItem) {
            return roomItem.ticketType.indexOf(tokenType);
        } else {
            return -1;
        }
    }

    onDisable(): void {
        this.removeEvents();

        // 清除可能存在的定时器
        Laya.timer.clearAll(this);
        
        // 仅在未进入游戏时，调用MainScene的requestMailData方法
        if (!this.isEntering) {
            this.requestMainSceneMailData();
        }
    }

    /**
     * 对话框关闭时，调用MainScene的requestMailData方法
     * 确保在JoinRoomDialog关闭后能够显示邮件提醒
     */
    private requestMainSceneMailData(): void {
        // 使用Signal.event触发事件
        Signal.event(GameEvent.EVENT_REQUEST_MAIL_DATA);
    }

    /**
     * 初始化事件监听
     */
    private initEvents(): void {
        // 注册顶部按钮点击事件
        for (let i = 0; i < TAB_COUNT; i++) {
            (this as any)[`tab${i}`].on(Laya.Event.CLICK, this, this.onTabClick, [i]);
        }

        // 注册其他事件
        Signal.on(`msg_${com.snake.socket.MessageType.MSG_QUERY_TOKEN}`, this, this.onRequestInfo);
        // 监听代币选择事件
        Signal.on(GameEvent.EVENT_TOKEN_SELECTED, this, this.onTokenSelected);
        this.img_di1.on(Laya.Event.CLICK, this, this.onCheakTab);
        this.btn_hideBox.on(Laya.Event.CLICK, this, this.onCloseTab);
        this.btn_font.on(Laya.Event.CLICK, this, this.onEnterMatch);
        if (GameSetting.Debug == 2) {
            // this.btn_watch.visible = true;
            this.btn_watch.on(Laya.Event.CLICK, this, this.onWatchMatch);
        }
        this.btn_invite.on(Laya.Event.CLICK, this, this.onInviteClick);

        // this.backLayer.on(Laya.Event.CLICK, this, this.closeDialog);

        // 列表渲染和选择处理
        this.list_token.renderHandler = Laya.Handler.create(this, this.onTokenItemRender, null, false);
        this.list_token.selectHandler = new Laya.Handler(this, this.handleSelectToken);
    }

    /**
     * 移除事件监听
     */
    private removeEvents(): void {
        // 移除消息监听
        Signal.off(`msg_${com.snake.socket.MessageType.MSG_QUERY_TOKEN}`, this, this.onRequestInfo);
        // 移除代币选择事件监听
        Signal.off(GameEvent.EVENT_TOKEN_SELECTED, this, this.onTokenSelected);

        // 移除UI事件
        this.img_di1.off(Laya.Event.CLICK, this, this.onCheakTab);
        this.btn_hideBox.off(Laya.Event.CLICK, this, this.onCloseTab);
        this.btn_font.off(Laya.Event.CLICK, this, this.onEnterMatch);
        this.btn_invite.off(Laya.Event.CLICK, this, this.onInviteClick);
        // this.backLayer.off(Laya.Event.CLICK, this, this.closeDialog);

        // 移除Tab点击事件
        for (let i = 0; i < TAB_COUNT; i++) {
            (this as any)[`tab${i}`].off(Laya.Event.CLICK, this, this.onTabClick);
        }

        // 移除列表事件
        this.list_token.renderHandler = null;
        this.list_token.selectHandler = null;
    }

    /**
     * 对战按钮点击事件
     */
    private onEnterMatch(): void {
        if (this.isEntering) {
            return;
        }
        if (!this.tokenData) {
            return;
        }

        if (this.roomData) {
            // 设置状态为true，防止连点
            this.isEntering = true;

            EnterRoomManager.goPvpArenaScene(
                this.roomData.id,
                this.roomData.ticketType[this.tokenIndex],
                this.roomData.ticketAmount[this.tokenIndex],
                this.tabIndex,
                this.tokenIndex,
                this.tokenData.symbol
            );

            // 3秒后恢复状态
            Laya.timer.once(3000, this, () => {
                this.isEntering = false;
            });
        }
        let roomData = { tabIndex: this.tabIndex, tokenIndex: this.tokenIndex };
        // 保存选择到localStorage
        this.saveTabAndTokenIndex();
    }
    /**
     * 观战按钮点击事件
     */
    private onWatchMatch(): void {
        if (this.isEntering) {
            return;
        }

        if (this.roomData) {
            // 设置状态为true，防止连点
            this.isEntering = true;
            let roomNo = "1_00_2_USDT_1001";
            if (GameSetting.roomNoTest) {
                roomNo = GameSetting.roomNoTest;
            }

            EnterRoomManager.watchPvpArenaScene(this.roomData.id, roomNo);

            // 3秒后恢复状态
            Laya.timer.once(3000, this, () => {
                this.isEntering = false;
            });
        }
    }

    /**
     * 处理代币选择事件
     */
    private onTokenSelected(tokenData: any): void {
        if (tokenData) {
            console.log("收到代币选择事件:", tokenData);

            // 如果传递了symbolId，使用symbolId找到正确的索引
            if (tokenData.symbolId !== undefined && this.roomData) {
                // 在当前房间的ticketType中查找symbolId对应的索引
                const foundIndex = this.roomData.ticketType.findIndex((item) => item === tokenData.symbolId);
                // this.roomData.ticketType = tokenData.ticketType;
                if (foundIndex !== -1) {
                    this.tokenIndex = foundIndex;
                } else {
                    // 如果找不到，才使用传递的索引
                    this.tokenIndex = tokenData.tokenIndex;
                }
            } else {
                // 兼容旧的方式，直接使用传递的索引
                this.tokenIndex = tokenData.tokenIndex;
            }

            // 如果传递了房间数据且与当前房间数据不同，则更新房间数据
            if (tokenData.roomData && this.roomData !== tokenData.roomData) {
                this.roomData = tokenData.roomData;
                // 可能需要更新其他相关的UI
            }

            // 确保tokenIndex在有效范围内
            if (this.tokenIndex < 0 || this.tokenIndex >= this.roomData.ticketType.length) {
                this.tokenIndex = 0;
            }

            // 更新代币信息显示
            this.updateTokenInfo(this.tokenIndex);

            // 保存选择到localStorage
            this.saveTabAndTokenIndex();
        }
    }

    /**
     * 显示代币选择面板
     */
    private onCheakTab(): void {
        // if (AssetManager.getTokenData()) {
        //     this.img_token_pad.visible = true;
        //     this.btn_hideBox.visible = true;
        // }
        let data = {
            tokenIndex: this.tokenIndex,
            roomData: this.roomData
        };
        ModuleManager.intance.openModule(ModuleName.ChooseCoinDialog, data);
    }

    /**
     * 关闭代币选择面板
     */
    private onCloseTab(): void {
        if (this.img_token_pad.visible) {
            this.btn_hideBox.visible = false;
            this.img_token_pad.visible = false;
        }
    }

    /**
     * Tab点击事件处理
     * @param index 被点击的Tab索引
     */
    private onTabClick(index: number): void {
        // if (this.tabIndex !== index) {
        //     this.tokenIndex = 0;
        // }
        this.tabIndex = index;
        if (!AssetManager.getTokenData()) return;

        // 更新所有Tab的状态
        this.updateTabsAppearance(index);

        // 设置当前房间类型
        this.roomType = ROOM_TYPES[index];

        // 更新房间数据
        this.updateRoomData();
    }

    /**
     * 更新所有Tab的外观
     * @param selectedIndex 当前选中的Tab索引
     */
    private updateTabsAppearance(selectedIndex: number): void {
        const SKIN_SELECTED = "res/main/newJoin/img_com_xuanzhong.png";
        const SKIN_UNSELECTED = "res/setup/settingNew/img_tab2.png";
        const STROKE_COLOR_SELECTED = "#ffffff";
        const STROKE_COLOR_UNSELECTED = "#7fb7ff";
        for (let i = 0; i < TAB_COUNT; i++) {
            const tab = (this as any)[`tab${i}`];
            const title = tab.getChildByName("tf_tit");
            const isSelected = selectedIndex === i;

            // 设置Tab外观
            tab.skin = isSelected ? SKIN_SELECTED : SKIN_UNSELECTED;
            title.color = isSelected ? STROKE_COLOR_SELECTED : STROKE_COLOR_UNSELECTED;
        }
    }

    /**
     * 更新房间数据列表
     */
    private updateRoomData(): void {
        // 获取当前房间类型的所有房间
        const dic = SheetDataManager.m_dicRoom?.values;
        const roomItems = dic.filter((item) => item.roomType == this.roomType && item.gameId == 100003);

        if (roomItems.length === 0) return;

        // 根据ticketType去重
        this.roomData = roomItems[0];

        // 更新UI
        // this.list_token.array = this.roomData.ticketType;

        // 只有在初始化时(setOpenData调用)才使用保存的tokenIndex
        // 在主动切换tab时，tokenIndex应该设置为0
        // if (this._isInitializing && this.getSavedTokenIndex() !== null) {
        //     const savedTokenIndex = this.getSavedTokenIndex();
        //     if (savedTokenIndex < this.roomData.ticketType.length) {
        //         this.list_token.selectedIndex = savedTokenIndex;
        //     } else {
        //         this.list_token.selectedIndex = 0;
        //     }
        //     this._isInitializing = false;
        // } else {
        //     this.list_token.selectedIndex = 0;
        // }

        // 更新显示的代币信息
        this.updateTokenInfo(this.tokenIndex);
    }

    private tokenData: TokenData;

    /**
     * 更新代币信息显示
     * @param roomItem 房间项
     */
    private updateTokenInfo(index: number): void {
        this.tokenIndex = index;
        this.tokenData = AssetManager.getTokenData().find((item) => item.symbolId == this.roomData.ticketType[index]);
        if (this.tokenData) {
            this.tf_coin.text = this.tokenData.symbol;
            this.img_coin.skin = GameResourceManager.getCurrencyIcon(this.tokenData.symbol);
            this.tf_number.text = String(this.roomData.ticketAmount[index]);
            var balance = `${NumberUtil.formatTrimZeroDecimal2(this.tokenData.balance, 5)}` + " " + this.tokenData.symbol;
            this.tf_balance.text = GameLanguageMgr.getLanguage(2010, balance);
        }
    }

    /**
     * 列表项渲染处理
     */
    private onTokenItemRender(cell: any, index: number): void {
        if (cell && cell.onChange) {
            cell.onChange(this.list_token.selectedIndex == index);
        }
    }

    /**
     * 代币选择处理
     */
    private handleSelectToken(index: number): void {
        if (index != -1) {
            this.updateTokenInfo(index);
            this.img_token_pad.visible = false;
            this.btn_hideBox.visible = false;
        }
    }

    /**
     * 请求资产信息
     */
    public requestCoinInfo(): void {
        const cmdId = com.snake.socket.MessageType.MSG_QUERY_TOKEN;
        HallWebSocket.send(cmdId);
    }

    /**
     * 获取资产信息回调
     */
    private onRequestInfo(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        const msgBody: com.snake.socket.SC_QUERY_TOKEN = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_QUERY_TOKEN);

        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            // 解析成可用的object格式
            // const parsedTokens = ComUtil.parseTokenData(msgBody.token);
            // 保存数据
            // AssetManager.getTokenData() = parsedTokens;
            this.onTabClick(this.tabIndex);
        }
    }

        /**
     * 保存当前的tabIndex和tokenIndex到localStorage
     */
    private saveTabAndTokenIndex(): void {
        try {
            localStorage.setItem(STORAGE_KEY_TAB + "_" + EnumMatch.ARENA_TYPE_PVP, this.tabIndex.toString());
            var tokenType = this.tokenData.symbolId;
            localStorage.setItem(EnumMatch.STORAGE_KEY_TOKEN + "_" + EnumMatch.ARENA_TYPE_PVP, tokenType + "");
        } catch (e) {
            console.error("保存到localStorage失败", e);
        }
    }

    /**
     * 从localStorage获取保存的tabIndex
     * @returns 保存的tabIndex或null
     */
    private getSavedTabIndex(): number | null {
        try {
            const savedValue = localStorage.getItem(STORAGE_KEY_TAB + "_" + EnumMatch.ARENA_TYPE_PVP,);
            if (savedValue !== null) {
                const value = parseInt(savedValue);
                if (!isNaN(value) && value >= 0 && value < TAB_COUNT) {
                    return value;
                }
            }
        } catch (e) {
            console.error("从localStorage获取tabIndex失败", e);
        }
        return null;
    }

      /**
     * 从localStorage获取保存的tokenIndex
     * @returns 保存的tokenIndex或null
     */
    private getSavedTokenType(): number | null {
        try {
            const savedValue = localStorage.getItem(EnumMatch.STORAGE_KEY_TOKEN + "_" + EnumMatch.ARENA_TYPE_PVP);
            if (savedValue !== null) {
                const value = parseInt(savedValue);
                if (!isNaN(value) && value >= 0) {
                    return value;
                }
            }
        } catch (e) {
            console.error("从localStorage获取tokenIndex失败", e);
        }
        return null;
    }

    /**
     * 关闭对话框
     */
    // private closeDialog(): void {
    //     this.close();
    // }

      private onInviteClick(): void {
        var pvpRoomIndex = this.tabIndex;
        if (pvpRoomIndex < 0) {
            pvpRoomIndex = 0;
        }
        var pvpTokenIndex = this.tokenIndex;

        if (pvpTokenIndex < 0) {
            pvpTokenIndex = 0;
        }

        var tokenType = this.tokenData.symbolId;

        // 创建包含房间信息的对象
        const roomInfo = {
            arenaType: EnumMatch.ARENA_TYPE_PVP,
            tabIndex: pvpRoomIndex, 
            tokenType: tokenType,
            // ticketAmount: ticketAmount,
            target: GlobalDataManager.playerDto.pid
        };

        // 添加room参数
        var code = JSON.stringify(roomInfo);

        const inviteUrl = Quick.getCustomRoomInviteUrl(code);
        doCopy(inviteUrl);
        NoticeMgr.notice(GameLanguageMgr.getLanguage(2011)); //复制成功，转发给好友。
    }
}
