const { regClass } = Laya;
import { languageListItemBase } from "./languageListItem.generated";
import LanguageItem from "../../data/sheetItem/language/LanguageItem";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import PlatFormManager from "../../common/PlatFormManager";

@regClass('SnCse2C4Qiq0GdwkQNE3PA==')
export class languageListItem extends languageListItemBase {
    private languageData: LanguageItem;
    public constructor() {
        super();
    }
    onEnable(): void {
        this.on(Laya.Event.CLICK, this, this.checkSelect);
    }

    public set dataSource(value: LanguageItem) {
        this.languageData = value;
        if (!value) {
            this.visible = false;
            return;
        }
        this.languageData = value;
        this.tf_language.text = value.language;
    }

    private checkSelect() {
        // 选中时，将当前语言id存储到全局数据管理器中
        const lanId = this.languageData.id;
        let lanType = GameLanguageMgr.getLanTypeById(lanId);
        GameLanguageMgr.FGM_SetLanguage(lanType);

        //获取当前链接
        let currentUrl = window.location.href;

        //查找里面有没有lang参数
        let url = new URL(currentUrl);
        if (url.searchParams.has("lan")) {
            //在链接里去掉lang参数
            url.searchParams.delete("lan");
            //在当前页面打开这个链接
            window.location.href = url.toString();
        } else {
            // 如果没有lang参数，则直接调用PlatFormManager.reload()
            PlatFormManager.reload();
        }
        this.event("checkSelect", this.languageData);
    }

    onChange(isSelect: boolean) {
        console.log("isSelect", isSelect);
        if (isSelect) {
            // 选中状态 - 黄色按钮样式
            this.img_btn.skin = "res/setup/settingNew/img_an1.png"; // 黄色背景图片
            this.tf_language.fontSize = 25;
            this.tf_language.color = "#FFFFFF"; // 白色文字
            this.tf_language.stroke = 2;
            this.tf_language.strokeColor = "#D26E02"; // 描边颜色
        } else {
            // 未选中状态 - 蓝色按钮样式
            this.img_btn.skin = "res/setup/settingNew/img_an2.png"; // 蓝色背景图片
            this.tf_language.fontSize = 25;
            this.tf_language.color = "#B8E5FE"; // 浅蓝色文字
            this.tf_language.stroke = 0; // 无描边
        }
    }

    onDisable(): void {
        this.languageData = null;
    }
}
