const { regClass } = Laya;
import GameLanguageMgr from "../../common/GameLanguageMgr";
import PlatFormManager from "../../common/PlatFormManager";
import GlobalDataManager from "../../global/GlobalDataManager";
import { Quick } from "../../utils/Quick";
import { MatchRuleTipSprBase } from "./MatchRuleTipSpr.generated";

@regClass('UalpXzx4SCmM0F5ivE8UDw==')
export class MatchRuleTipSpr extends MatchRuleTipSprBase {
    private canClose: boolean = true;
    type: number = 0;

    public constructor() {
        super();
    }

    onEnable(): void {
        // this.btn_refresh.on(Laya.Event.CLICK, this, this.onRefresh);
        // 注册超链接点击事件
        // this.alertDesc.on(Laya.Event.LINK, this, this.onLink);
        this.check_remeber.on(Laya.Event.CLICK, this, this.onCheckBoxClick);
        this.btn_close.on(Laya.Event.CLICK, this, this.close);
        this.tf_remeber.text = GameLanguageMgr.getLanguage(610107);
    }

    private onCheckBoxClick() {
        // this.check_remeber.selected = !this.check_remeber.selected;
        var isRemeber = this.check_remeber.selected ? "1" : "0";
        console.log("isRemeber:", isRemeber);
        Laya.LocalStorage.setItem(Quick.COOKIE_RULE_KEY + GlobalDataManager.playerDto.pid + "_" + this.type, isRemeber);
    }

    // onLink(data: any) {
    //     console.log("点击了超链接：" + data);
    //     if (data) {
    //         Quick.onOpenUrlView(data);
    //     }
    // }
    // onRefresh() {
    //     PlatFormManager.reload();
    // }

    public setOpenData(ruleType: number, title: string, content: string) {
        this.type = ruleType;
        this.alertDesc.text = content;
        this.alertDesc.height = this.alertDesc.textField.textHeight + 20;
    }

    onDisable(): void {}

    close(type?: string): void {
        if (this.canClose) this.removeSelf();
    }
}
